import {createRequire} from 'node:module';
import assert from 'node:assert/strict';
import {writeFile} from 'node:fs/promises';
import {replacementUri,urlOfSavePath} from '../variants/next/lib/resource.js';
const URI=createRequire(new URL('../variants/current/lib/index.js',import.meta.url))('urijs');
const parts=['a','b.html','x_y','c-d','a.b.c','','.','..','%2e','%2F','%3A','%ZZ','😀','日本語','a b','c:d','x&y','a?b','a#b'];
let state=123456789,checked=0,errors=0;
const random=()=>{state^=state<<13;state^=state>>>17;state^=state<<5;return(state>>>0)/4294967296;};
const path=()=>Array.from({length:1+Math.floor(random()*6)},()=>parts[Math.floor(random()*parts.length)]).join(random()<.1?'\\':'/')+(random()<.2?'/':'');
const result=fn=>{try{return {value:fn().toString()};}catch(e){return {error:e.name,message:e.message};}};
for(let i=0;i<100000;i++){
 const a=path(),b=random()<.1?a:path();
 const before=result(()=>URI(urlOfSavePath(a)).relativeTo(urlOfSavePath(b))),after=result(()=>replacementUri(a,b));
 assert.deepEqual(after,before,JSON.stringify({a,b}));if(before.error)errors++;checked++;
}
const report={passed:true,checked,matchingErrors:errors,seed:123456789};
await writeFile(new URL('../logs/fuzz-redirect.json',import.meta.url),JSON.stringify(report));console.log(JSON.stringify(report));

