import fs from 'node:fs/promises';
import net from 'node:net';
import path from 'node:path';
import {pathToFileURL} from 'node:url';
import {createHash} from 'node:crypto';
import {performance} from 'node:perf_hooks';
import {Session} from 'node:inspector/promises';
import assert from 'node:assert/strict';
net.Socket.prototype.connect=function(){throw new Error('Network disabled in local MDN replay');};
const root=new URL('../',import.meta.url).pathname;
export const fixtureInfo={'mdn-local':{pages:3,stylesheets:1,concurrency:8,maxDepth:0,htmlBytes:101908,cssBytes:22576,description:'Saved MDN document replay with real MDN lifecycle, plus CSS extracted from its 16 inline style blocks; local acquisition, real output writes and disposal.'}};
export async function makeRunner(variant,pressure){
 const name=variant===0?'current':(process.env.WSE_CANDIDATE || 'marker');
 const engine=root+'variants/'+name+'/lib/index.js';
 const lifecycle=pathToFileURL(root+'variants/'+name+'/mdn/life-cycle.js').href;
 const {MdnDownloader}=await import(pathToFileURL(root+'variants/'+name+'/mdn/mdn-downloader.js'));
 const api=await import(pathToFileURL(engine));
 const directory=await fs.mkdtemp(root+'tmp/mdn-'+variant+'-');let counter=0;
 const config=path.join(directory,'options.mjs');
 await fs.writeFile(config,`
import base from ${JSON.stringify(lifecycle)};
import {readFile} from 'node:fs/promises';
const html=await readFile(${JSON.stringify(root+'fixtures/mdn.html')},'utf8');
const css=await readFile(${JSON.stringify(root+'fixtures/mdn-inline.css')},'utf8');
export default {...base,initialUrl:[],init:[],maxDepth:0,concurrency:8,adjustConcurrencyPeriod:undefined,
meta:{...base.meta,locale:'en-US'},createLogger:()=>({trace(){},debug(){},info(){},warn(){},error(){},isTraceEnabled(){return false;}}),
download:[res=>{res.body=res.type===2?html:res.type===3?css:Buffer.from('fixture');res.meta.headers={'content-type':res.type===2?'text/html':res.type===3?'text/css':'application/octet-stream'};return res;}]};
`);
 async function work(){
  const output=path.join(directory,'out-'+counter++);const errors=[];let live=[];
  const crawler=new MdnDownloader(pathToFileURL(config).href,{localRoot:output});
  crawler.handleError=(...args)=>errors.push(args);
  try{
   await crawler.init;crawler.stop();
   for(let i=0;i<4;i++){
    const html=i<3;const url=html?'https://developer.mozilla.org/en-US/docs/Web/API/Canvas_API/Tutorial/Using_images_'+i:'https://developer.mozilla.org/static/replay.css';
    const res=await crawler.pipeline.createResource(html?api.resource.ResourceType.Html:api.resource.ResourceType.Css,0,url,url);
    crawler.addProcessedResource(res);
    if(pressure)live.push(new Array(65536).fill(123));
   }
   await crawler.start();await crawler.onIdle();assert.deepEqual(errors,[]);
  }finally{await crawler.dispose();live=[];}
  return output;
 }
 async function verify(output){
  const entries=(await fs.readdir(output,{recursive:true,withFileTypes:true})).filter(x=>x.isFile()).map(x=>path.relative(output,path.join(x.parentPath,x.name))).sort();
  assert.equal(entries.length,4);
  const hash=createHash('sha256');let bytes=0;
  for(const entry of entries){assert.ok(!entry.includes('.wse-stage-'));const body=await fs.readFile(path.join(output,entry));bytes+=body.length;hash.update(entry.split(path.sep).join('/')).update('\0').update(body);}
  await fs.rm(output,{recursive:true,force:true});return {count:entries.length,outputBytes:bytes,sha256:hash.digest('hex')};
 }
 return {
  async warm(){await verify(await work());},
  async sample(key){
   global.gc();const heapBefore=process.memoryUsage().heapUsed;const start=performance.now();
   const output=await work();const totalMs=performance.now()-start;const memory=process.memoryUsage();
   const result=await verify(output);global.gc();const retained=process.memoryUsage().heapUsed;
   return {case:key,totalMs,...result,heapAfter:memory.heapUsed,heapBefore,retainedHeapDelta:retained-heapBefore,rss:memory.rss};
  },
  async profile(key,prefix){
   global.gc();const session=new Session();session.connect();await session.post('Profiler.enable');await session.post('Profiler.start');
   await session.post('HeapProfiler.startSampling',{samplingInterval:4096,includeObjectsCollectedByMajorGC:true,includeObjectsCollectedByMinorGC:true});
   const output=await work();const {profile}=await session.post('HeapProfiler.stopSampling');const {profile:cpu}=await session.post('Profiler.stop');session.disconnect();
   await fs.writeFile(prefix+'.heapprofile',JSON.stringify(profile));await fs.writeFile(prefix+'.cpuprofile',JSON.stringify(cpu));
   const stack=[profile.head];let bytes=0;while(stack.length){const n=stack.pop();bytes+=n.selfSize;stack.push(...n.children);}
   return {case:key,...await verify(output),sampledBytes:bytes};
  },
  async close(){await fs.rm(directory,{recursive:true,force:true});}
 };
}

