import {createRequire} from 'node:module';
import {Session} from 'node:inspector/promises';
import {writeFile} from 'node:fs/promises';
import assert from 'node:assert/strict';
import {replacementUri,urlOfSavePath} from '../variants/next/lib/resource.js';
const root=new URL('../',import.meta.url),URI=createRequire(new URL('variants/current/lib/index.js',root))('urijs');
const baseline=(a,b)=>URI(urlOfSavePath(a)).relativeTo(urlOfSavePath(b));
const paths=Array.from({length:4096},(_,i)=>[`example.test/new/sub/page-${i}.html`,`example.test/old/page-${i}.html`]);
for(const [a,b] of paths)assert.equal(replacementUri(a,b).toString(),baseline(a,b).toString());
let sink=0;
function work(fn,pressure){let live=[];for(let i=0;i<paths.length;i++){const [a,b]=paths[i];sink+=fn(a,b).toString().length;if(pressure&&i%64===0){live.push(new Array(32768).fill(123));if(live.length>8)live.shift();}}}
const results=[];
for(const pressure of [false,true]){
 for(const fn of [baseline,replacementUri])for(let i=0;i<3;i++)work(fn,pressure);
 for(let round=0;round<3;round++)for(let k=0;k<3;k++){
  const variant=(round+k)%3;global.gc();
  const session=new Session();session.connect();await session.post('HeapProfiler.startSampling',{samplingInterval:4096,includeObjectsCollectedByMajorGC:true,includeObjectsCollectedByMinorGC:true});
  work(variant===0?baseline:replacementUri,pressure);
  const {profile}=await session.post('HeapProfiler.stopSampling');session.disconnect();
  await writeFile(new URL(`profiles/relative-p${Number(pressure)}-r${round}-v${variant}.heapprofile`,root),JSON.stringify(profile));
  const stack=[profile.head];let bytes=0;while(stack.length){const x=stack.pop();bytes+=x.selfSize;stack.push(...x.children);}
  results.push({pressure,round,variant,bytes});
 }
}
await writeFile(new URL('runs/relative-allocation.json',root),JSON.stringify({pairs:4096,results,sink},null,2));

